 const acc=new Float64Array(C);let wsum=0,fish=0,plant=0,raw=0;
 for(const f of F){const gz=[0,1,2].map(k=>{let z=meta.gb[k];for(let j=0;j<d;j++)z+=f[j]*G[j*3+k];return z*meta.gT});const gm=Math.max(...gz),ge=gz.map(z=>Math.exp(z-gm)),gs=ge[0]+ge[1]+ge[2];const pa=ge[0]/gs,pp=ge[1]/gs;fish=Math.max(fish,pa);plant=Math.max(plant,pp);
  const kn=new Float32Array(C).fill(-1);for(let i=0;i<np;i++){let v=0;const o=i*d;for(let j=0;j<d;j++)v+=f[j]*P[o+j];const c=meta.pl[i];if(v>kn[c])kn[c]=v;if(meta.kind[c]===0&&v>raw)raw=v}
  const z=new Float64Array(C);let zm=-1e9;for(let c=0;c<C;c++){let v=meta.b[c];for(let j=0;j<d;j++)v+=f[j]*W[j*C+c];z[c]=(v*meta.T0+meta.a*kn[c])*meta.T;if(z[c]>zm)zm=z[c]}
  let zs=0;for(let c=0;c<C;c++){z[c]=Math.exp(z[c]-zm);zs+=z[c]}const wt=pa+pp+.05;for(let c=0;c<C;c++)acc[c]+=wt*z[c]/zs;wsum+=wt}
