 const ex=[...acc].map((v,c)=>[meta.ids[c],v/wsum,meta.kind[c]]).sort((a,b)=>b[1]-a[1]);
 const animals=ex.filter(e=>e[2]===0),plants=ex.filter(e=>e[2]===1);
 const top=animals.slice(0,8).map(([id,p])=>({id,p})).filter(o=>A.BY[o.id]);const ptop=plants.slice(0,3).map(([id,p])=>({id,p}));
 const ap=animals.reduce((s2,e)=>s2+e[1],0)||1;top.forEach(o=>o.p=o.p/ap);
 let sure=top.length>0&&top[0].p>=.8&&(top[0].p-(top[1]?top[1].p:0))>=.4&&fish>=.6;
 if(top.length&&TWINS[top[0].id]){sure=false;TWINS[top[0].id].forEach((t,k)=>{if(A.BY[t]&&!top.slice(0,3).some(o=>o.id===t)){const i=top.findIndex(o=>o.id===t);const o=i>=0?top.splice(i,1)[0]:{id:t,p:.01};top.splice(1+k,0,o)}})}const known=sure||(top.length>0&&top[0].p>=.2&&raw>=.55);
