const BEH=[['eat','Not eating','noeat',12],['gasping','Gasping at the surface','gasping',15],['clamped','Fins clamped to the body','clamped',8],['flashing','Rubbing on decor','flashing',8],['hide','Hiding or very still','lethargic',8],['upsidedown','Swimming sideways / struggling','upsidedown',18],['dust','Looks dusty gold under a torch','golddust',14]];
