function px(img,W){const s=W/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height);const c=document.createElement('canvas');c.width=Math.max(8,Math.round((img.naturalWidth||img.width)*s));c.height=Math.max(8,Math.round((img.naturalHeight||img.height)*s));const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(img,0,0,c.width,c.height);return{c,g,w:c.width,h:c.height,d:g.getImageData(0,0,c.width,c.height).data}}
function colourStats(P,mask){let n=0,sat=0,red=0;for(let i=0;i<P.w*P.h;i++){if(!mask[i])continue;const r=P.d[i*4],g=P.d[i*4+1],b=P.d[i*4+2],mx=Math.max(r,g,b),mn=Math.min(r,g,b);n++;sat+=mx?(mx-mn)/mx:0;if(r>140&&r>g*1.6&&r>b*1.5)red++}return{sat:n?sat/n:0,red:n?red/n:0,n}}
function refStats(id){if(refCache[id])return refCache[id];refCache[id]=new Promise(ok=>{const im=new Image();im.crossOrigin='anonymous';im.onload=()=>{try{const P=px(im,160);const m=new Uint8Array(P.w*P.h);for(let i=0;i<m.length;i++)m[i]=P.d[i*4+3]>200?1:0;ok(colourStats(P,m))}catch(e){ok(null)}};im.onerror=()=>ok(null);im.src=D.src(id)});return refCache[id]}
