function refFeats(id){const k='f_'+id;if(refCache[k])return refCache[k];refCache[k]=new Promise(ok=>{const im=new Image();im.crossOrigin='anonymous';im.onload=()=>{try{const c=document.createElement('canvas');c.width=im.width*1.33;c.height=im.height*1.33;const g=c.getContext('2d');g.fillStyle='#123028';g.fillRect(0,0,c.width,c.height);g.drawImage(im,(c.width-im.width)/2,(c.height-im.height)/2);ok(feats(c))}catch(e){ok(null)}};im.onerror=()=>ok(null);im.src=D.src(id)});return refCache[k]}
