 for(let i=0;i<N;i++){const r=d[i*4],g=d[i*4+1],b=d[i*4+2],mx=Math.max(r,g,b),mn=Math.min(r,g,b);L[i]=.299*r+.587*g+.114*b;S[i]=mx?(mx-mn)/mx:0;cand[i]=(L[i]>140&&S[i]<.3)?1:0}
