 if(h.nofish)return `<div class="res nofish"><div class="himg"><img src="${h.img.src}" alt=""></div><span class="nfic">${I('search',26)}</span><div class="nft"><b>No fish found</b><span>We couldn't see a fish or aquarium animal in this photo, so we can't check its health. Take a clear side photo of one fish.</span></div><div class="nfb"><button class="btn sm grad" data-sc="hagain">${I('camera',15)}Try another photo</button><button class="btn sm ghost" data-sc="hforce">Check anyway</button></div></div>`;
 if(h.err)return `<div class="res"><p>${esc(h.err)}</p><button class="btn grad" data-sc="hagain">Try again</button></div>`;
