 let open=0,cells=0;const cs=8;for(let y=Math.floor(H*.2);y<H*.7-cs;y+=cs)for(let x=0;x<W-cs;x+=cs){let e=0;for(let yy=y;yy<y+cs;yy++)for(let xx=x;xx<x+cs-1;xx++)e+=Math.abs(lum[yy*W+xx+1]-lum[yy*W+xx]);cells++;if(e/(cs*cs)<4)open++}
