function tkVisionNotes(v){const o=[];if(!v)return o;
 if(v.mean<45)o.push(['warn','The photo is very dark','Turn the tank light on (room lights off) for a clearer check. Dark photos hide fish and plants.']);
 if(v.mean>215)o.push(['tip','The photo is very bright','Glare or flash can hide details. Take it straight on with the flash off.']);
 if(v.G>v.R*1.18&&v.G>v.B*1.12&&v.sd<42)o.push(['warn','The water looks green','A green haze usually means floating algae (green water). Reduce light hours, avoid direct sun, do water changes, and consider a UV clarifier.']);
 if(v.warm>.45&&v.mean>60&&v.R>v.B*1.3)o.push(['tip','The water looks tea-coloured','Usually tannins from wood or leaves. Harmless and liked by many soft-water fish; use carbon if you prefer clear water.']);
 if(v.sd<28&&v.mean>80&&!(v.G>v.R*1.18))o.push(['warn','The water may be cloudy','Low contrast across the photo can mean cloudy water (bacterial bloom or fine particles). Check ammonia and nitrite, and don’t overfeed.']);
 if(v.plantCover<.04)o.push(['tip','Very few plants are visible','Plants use up nitrate, compete with algae and give fish cover. Easy starters: Java fern, Anubias, floating plants.']);
 else if(v.plantCover>.55)o.push(['tip','The tank is heavily planted','Great for water quality. Keep an open area at the front for swimming and trim regularly.']);
 if(v.open<.08&&v.plantCover>.25)o.push(['tip','Little open swimming space','Active fish like tetras, danios and rainbows need open water in the middle and front.']);
 return o}
