 const hs=TK.ai&&TK.ai.hardscape||{};
 items=items.map(i=>{if(/needs a cave/.test(i.title))return hs.caves?null:Object.assign({},i,{level:'tip',title:i.title.replace('needs a cave','needs a cave to hide in'),text:'If there is no cave yet, add one per fish (clay pot, rock cave or pleco cave).'});
  if(/needs driftwood/.test(i.title))return hs.wood?null:Object.assign({},i,{level:'tip',text:'Make sure there is real driftwood in the tank: it rasps wood for fibre.'});
  if(/needs sand/.test(i.title))return /sand/.test(TK.ai&&TK.ai.substrate||'')?null:Object.assign({},i,{level:'tip'});return i}).filter(Boolean);
 const sec={compat:[],stock:[],plants:[],layout:[],equip:[],water:[]};
 items.forEach(i=>{const T=i.title;if(/ \+ |Only one|own tank|eat the small|Temperatures|pH needs/.test(T))sec.compat.push(i);else if(/Overstock|Nearly full|too small|keep at least|Bowls/.test(T))sec.stock.push(i);else if(/light|CO₂|root in|eat or uproot|grows on|feeds through/.test(T))sec.plants.push(i);else if(/cave|driftwood|sand|land/.test(T))sec.layout.push(i);else if(/heater|filter|Heater|Filter|summer/.test(T))sec.equip.push(i);else sec.water.push(i)});
